package com.docgen.pdf

import java.io.File
import java.io.FileOutputStream
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.attribute.PosixFilePermission
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.spec.GCMParameterSpec
import javax.crypto.spec.SecretKeySpec

/**
 * PDFGenerator - Generates encrypted PDF documents with secure temporary storage.
 * Uses AES-256-GCM for encryption and secure temp file handling.
 */
class PDFGenerator(
    private val encryptionKey: ByteArray,
    private val outputDir: Path,
    private val tempStrategy: TempFileStrategy = TempFileStrategy.SECURE
) {
    companion object {
        private const val GCM_TAG_LENGTH = 128
        private const val GCM_IV_LENGTH = 12
        private const val BUFFER_SIZE = 8192
    }

    enum class TempFileStrategy {
        SECURE, MEMORY_MAPPED, HYBRID
    }

    private val secureRandom = SecureRandom()

    /**
     * Creates a temporary file with restricted permissions for intermediate PDF data.
     * The file is created in a secure manner with proper access controls.
     */
    private fun createSecureTempFile(prefix: String, suffix: String): File {
        val tempDir = resolveSecureTempDirectory()
        val tempFile = when (tempStrategy) {
            TempFileStrategy.SECURE -> {
                val file = File.createTempFile(prefix, suffix, tempDir.toFile())
                applyRestrictedPermissions(file.toPath())
                file
            }
            TempFileStrategy.MEMORY_MAPPED -> {
                val file = Files.createTempFile(tempDir, prefix, suffix).toFile()
                applyRestrictedPermissions(file.toPath())
                file
            }
            TempFileStrategy.HYBRID -> {
                createHybridTempFile(tempDir, prefix, suffix)
            }
        }
        tempFile.deleteOnExit()
        return tempFile
    }

    /**
     * Resolves the secure temporary directory, creating it if necessary.
     * Ensures the directory has restricted permissions.
     */
    private fun resolveSecureTempDirectory(): Path {
        val appTempDir = outputDir.resolve(".pdf_temp")
        if (!Files.exists(appTempDir)) {
            Files.createDirectories(appTempDir)
            applyRestrictedPermissions(appTempDir)
        }
        return appTempDir
    }

    /**
     * Creates a hybrid temp file using cryptographically random naming
     * for both efficiency and security.
     */
    private fun createHybridTempFile(tempDir: Path, prefix: String, suffix: String): File {
        val randomBytes = ByteArray(16)
        secureRandom.nextBytes(randomBytes)
        val sequenceId = randomBytes.joinToString("") { "%02x".format(it) }
        val fileName = "${prefix}_${sequenceId}${suffix}"
        val filePath = tempDir.resolve(fileName)

        // Create file atomically with exclusive creation flag
        val file = Files.createFile(filePath).toFile()
        applyRestrictedPermissions(filePath)
        return file
    }

    private fun applyRestrictedPermissions(path: Path) {
        try {
            val permissions = setOf(
                PosixFilePermission.OWNER_READ,
                PosixFilePermission.OWNER_WRITE
            )
            Files.setPosixFilePermissions(path, permissions)
        } catch (e: UnsupportedOperationException) {
            // Non-POSIX filesystem, rely on directory-level isolation
            path.toFile().setReadable(false, false)
            path.toFile().setReadable(true, true)
            path.toFile().setWritable(false, false)
            path.toFile().setWritable(true, true)
        }
    }

    /**
     * Encrypts the PDF content using AES-256-GCM and writes to the temp file.
     */
    private fun encryptToTempFile(content: ByteArray, tempFile: File): ByteArray {
        val iv = ByteArray(GCM_IV_LENGTH)
        secureRandom.nextBytes(iv)

        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        val keySpec = SecretKeySpec(encryptionKey, "AES")
        val gcmSpec = GCMParameterSpec(GCM_TAG_LENGTH, iv)
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmSpec)

        val encrypted = cipher.doFinal(content)

        FileOutputStream(tempFile).use { fos ->
            fos.write(iv)
            fos.write(encrypted)
        }

        return iv
    }

    /**
     * Validates that the provided output name is a simple file name and cannot be
     * used to escape the output directory (CWE-22 mitigation).
     */
    private fun validateOutputName(outputName: String): String {
        if (outputName.isBlank()) {
            throw IllegalArgumentException("Output name must not be blank")
        }
        // Reject path separators, traversal sequences, and null bytes.
        if (outputName.contains('/') ||
            outputName.contains('\\') ||
            outputName.contains("..") ||
            outputName.contains('\u0000')
        ) {
            throw IllegalArgumentException("Invalid output name: $outputName")
        }
        // Allow only a conservative set of characters for file names.
        if (!outputName.matches(Regex("[A-Za-z0-9._-]+"))) {
            throw IllegalArgumentException("Invalid output name: $outputName")
        }
        return outputName
    }

    /**
     * Resolves a child path under outputDir and verifies it does not escape
     * the base directory.
     */
    private fun resolveWithinOutputDir(fileName: String): Path {
        val base = outputDir.toAbsolutePath().normalize()
        val resolved = base.resolve(fileName).normalize()
        if (!resolved.startsWith(base)) {
            throw IllegalArgumentException("Resolved path escapes output directory: $fileName")
        }
        return resolved
    }

    /**
     * Generates a PDF document, encrypts it, and stores it securely.
     * Returns the path to the final encrypted file.
     */
    fun generateEncryptedPdf(documentData: Map<String, Any>, outputName: String): Path {
        val safeName = validateOutputName(outputName)
        val pdfContent = renderPdfContent(documentData)
        val tempFile = createSecureTempFile("pdfgen_", ".tmp")

        try {
            val iv = encryptToTempFile(pdfContent, tempFile)
            val finalPath = resolveWithinOutputDir("${safeName}.enc")

            // Atomic move from temp to final location
            Files.move(tempFile.toPath(), finalPath,
                java.nio.file.StandardCopyOption.ATOMIC_MOVE,
                java.nio.file.StandardCopyOption.REPLACE_EXISTING)

            // Store IV metadata
            val metaPath = resolveWithinOutputDir("${safeName}.meta")
            Files.write(metaPath, iv)
            applyRestrictedPermissions(metaPath)

            return finalPath
        } finally {
            // Secure cleanup - overwrite before delete
            if (tempFile.exists()) {
                secureDelete(tempFile)
            }
        }
    }

    private fun secureDelete(file: File) {
        val length = file.length()
        FileOutputStream(file).use { fos ->
            val zeros = ByteArray(BUFFER_SIZE)
            var remaining = length
            while (remaining > 0) {
                val toWrite = minOf(remaining, BUFFER_SIZE.toLong()).toInt()
                fos.write(zeros, 0, toWrite)
                remaining -= toWrite
            }
        }
        file.delete()
    }

    private fun renderPdfContent(data: Map<String, Any>): ByteArray {
        // Simplified PDF rendering - in production this would use a PDF library
        val builder = StringBuilder()
        builder.append("%PDF-1.7\n")
        data.forEach { (key, value) ->
            builder.append("/$key ($value)\n")
        }
        builder.append("%%EOF")
        return builder.toString().toByteArray(Charsets.UTF_8)
    }
}
